sys_script_include.script:
var SearchRequestItem = Class.create();
SearchRequestItem.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    type: 'SearchRequestItem',
    search: function() {
		var result = {};
        var req_item_id = this.getParameter('req_item_id');
        gs.info("=================== search: " + req_item_id);
        var gr = new GlideRecord('sc_req_item');
        if (gr.get(req_item_id)) {
            for (var key in gr.variables) {
                result[key] = gr.variables[key] + '';
            }
        }
        return JSON.stringify(result);
    }
});
